const body = $json.body || $json;
const { task_id, created_by, impacts } = body;

if (!task_id || !Array.isArray(impacts) || impacts.length === 0) {
  return { json: { error: 'task_id and impacts array required' } };
}

// Build individual INSERTs to handle varying columns per row
const statements = impacts.map(i => {
  const c = ['task_id', 'item_type', 'status', 'created_by'];
  const v = [task_id, `'${i.item_type}'`, `'${i.status || 'A'}'`, `'${(created_by || 'system').replace(/'/g, "''") }'`];

  if (i.page_id != null) { c.push('page_id'); v.push(i.page_id); }
  if (i.schema_name) { c.push('schema_name'); v.push(`'${i.schema_name}'`); }
  if (i.object_name) { c.push('object_name'); v.push(`'${i.object_name.replace(/'/g, "''") }'`); }
  if (i.component_id != null) { c.push('component_id'); v.push(i.component_id); }
  if (i.component_name) { c.push('component_name'); v.push(`'${i.component_name.replace(/'/g, "''") }'`); }
  if (i.description) { c.push('description'); v.push(`'${i.description.replace(/'/g, "''") }'`); }

  return `INSERT INTO agile.agile_impacts (${c.join(', ')}) VALUES (${v.join(', ')}) RETURNING id`;
}).join(';\n');

const sql = statements + ';';

return { json: { sql, task_id, count: impacts.length } };
